import time
import heapq


class KVCache:
    def __init__(self, capacity, ttl_seconds, clock=None):
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise ValueError("capacity must be a non-bool integer >= 0")
        if capacity < 0:
            raise ValueError("capacity must be a non-bool integer >= 0")
        if isinstance(ttl_seconds, bool):
            raise ValueError("ttl_seconds must be a finite non-bool number >= 0")
        if not isinstance(ttl_seconds, (int, float)):
            raise ValueError("ttl_seconds must be a finite non-bool number >= 0")
        if ttl_seconds != ttl_seconds or ttl_seconds in (float("inf"), float("-inf")):
            raise ValueError("ttl_seconds must be a finite non-bool number >= 0")
        if ttl_seconds < 0:
            raise ValueError("ttl_seconds must be a finite non-bool number >= 0")

        self._capacity = capacity
        self._ttl = ttl_seconds
        self._clock = clock if clock is not None else time.monotonic
        self._data = {}       # key -> [value, expiry, counter]
        self._counter = 0     # monotonic usage counter for LRU ordering

    def _now(self):
        return self._clock()

    def _purge_expired(self, now):
        expired = [k for k, (v, exp, c) in self._data.items() if now >= exp]
        for k in expired:
            del self._data[k]

    def get(self, key):
        now = self._now()
        self._purge_expired(now)
        item = self._data.get(key)
        if item is None:
            return None
        item[2] = self._counter
        self._counter += 1
        return item[0]

    def put(self, key, value):
        now = self._now()
        self._purge_expired(now)

        if self._capacity == 0 or self._ttl == 0:
            # Nothing is stored.
            if key in self._data:
                del self._data[key]
            return

        if key in self._data:
            # Updating an existing live entry: refresh value, TTL, and recency.
            self._data[key] = [value, now + self._ttl, self._counter]
            self._counter += 1
            return

        # Evict LRU if at capacity (all expired entries already removed above).
        while len(self._data) >= self._capacity:
            lru_key = min(self._data, key=lambda k: self._data[k][2])
            del self._data[lru_key]

        self._data[key] = [value, now + self._ttl, self._counter]
        self._counter += 1

    def delete(self, key):
        now = self._now()
        self._purge_expired(now)
        if key in self._data:
            del self._data[key]
            return True
        return False
